select * from
  ( select      debitamount,  val_name
     from ex_provarch  where status=1 and (dat>=:dat1 and dat<=:dat2) 
and ex_id=:ex_id
)
  pivot
  ( sum(debitamount) for val_name in ('USD' as USD,'EUR' as EUR,
                  'RUR' as RUR,'GBP' as GBP
                  )  )

select * from
  ( select      debitamount,  val_name
     from ex_provarch  where status=2 and (dat>=:dat1 and dat<=:dat2) 
  and ex_id=:ex_id
)
  pivot
  ( sum(debitamount) for val_name in ('USD' as USD,'EUR' as EUR,
                  'RUR' as RUR,'GBP' as GBP
                  )  )
